using System;
using System.Linq;
using System.Threading;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace NCoreUtils.Localization.Generator
{
    [Generator(LanguageNames.CSharp)]
    public sealed class LocalizerGenerator : IIncrementalGenerator
    {
        private const string AttributeName = "NCoreUtils.Localization.GeneratedLocalizerAttribute";

        private const string AttributeSource = """
            // <auto-generated/>
            #nullable enable

            namespace NCoreUtils.Localization
            {
                /// <summary>
                /// Generates a localizer from the <c>*.{suffix}.{locale}.i18n.yaml</c> additional files.
                /// </summary>
                [global::System.AttributeUsage(global::System.AttributeTargets.Interface, AllowMultiple = false, Inherited = false)]
                internal sealed class GeneratedLocalizerAttribute : global::System.Attribute
                {
                    /// <summary>
                    /// Suffix of the files to use, if empty all localization files are used.
                    /// </summary>
                    public string Suffix { get; }

                    public GeneratedLocalizerAttribute(string suffix = "")
                    {
                        Suffix = suffix;
                    }
                }
            }

            """;

        public void Initialize(IncrementalGeneratorInitializationContext context)
        {
            context.RegisterPostInitializationOutput(static ctx
                => ctx.AddSource("GeneratedLocalizerAttribute.g.cs", SourceText.From(AttributeSource, System.Text.Encoding.UTF8)));

            var files = context.AdditionalTextsProvider
                .Where(static file => file.Path.EndsWith(LocalizationFileParser.Extension, StringComparison.Ordinal))
                .Select(LocalizationFileParser.Parse);

            context.RegisterSourceOutput(files, static (ctx, file) =>
            {
                foreach (var diagnostic in file.Diagnostics)
                {
                    ctx.ReportDiagnostic(diagnostic.ToDiagnostic());
                }
            });

            var allFiles = files
                .Collect()
                .Select(static (items, _) => new EquatableArray<LocalizationFile>(
                    [.. items.OrderBy(static file => file.Path, StringComparer.Ordinal)]));

            var targets = context.SyntaxProvider.ForAttributeWithMetadataName(
                AttributeName,
                static (node, _) => node is InterfaceDeclarationSyntax,
                GetTarget);

            context.RegisterSourceOutput(targets.Combine(allFiles), static (ctx, input) => Generate(ctx, input.Left, input.Right));
        }

        private static LocalizerTarget GetTarget(GeneratorAttributeSyntaxContext context, CancellationToken cancellationToken)
        {
            var symbol = (INamedTypeSymbol)context.TargetSymbol;
            var syntax = (InterfaceDeclarationSyntax)context.TargetNode;
            var location = LocationInfo.From(syntax.Identifier.GetLocation());
            var attribute = context.Attributes[0];
            var suffix = attribute.ConstructorArguments.Length > 0
                ? attribute.ConstructorArguments[0].Value as string ?? string.Empty
                : string.Empty;
            var isValid = syntax.Modifiers.Any(SyntaxKind.PartialKeyword)
                && !symbol.IsGenericType
                && symbol.ContainingType is null;
            return new(
                symbol.ContainingNamespace.IsGlobalNamespace
                    ? null
                    : symbol.ContainingNamespace
                        .ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)
                        .Substring("global::".Length),
                symbol.Name,
                symbol.DeclaredAccessibility == Accessibility.Public ? "public" : "internal",
                suffix,
                location,
                isValid ? null : DiagnosticInfo.Create(Diagnostics.InvalidTarget, location, symbol.Name));
        }

        private static void Generate(SourceProductionContext context, LocalizerTarget target, EquatableArray<LocalizationFile> allFiles)
        {
            if (target.Error is not null)
            {
                context.ReportDiagnostic(target.Error.ToDiagnostic());
                return;
            }
            var files = allFiles.Where(file => file.MatchesSuffix(target.Suffix)).ToList();
            if (files.Any(file => file.HasErrors))
            {
                return; // already reported for the file itself
            }
            if (files.Count == 0)
            {
                var pattern = target.Suffix.Length == 0 ? "*.{locale}.i18n.yaml" : $"*.{target.Suffix}.{{locale}}.i18n.yaml";
                context.ReportDiagnostic(DiagnosticInfo.Create(Diagnostics.NoMatchingFiles, target.Location, pattern, target.Name).ToDiagnostic());
            }
            var (root, diagnostics) = LocalizationMerger.Merge(target, files);
            foreach (var diagnostic in diagnostics)
            {
                context.ReportDiagnostic(diagnostic.ToDiagnostic());
            }
            if (diagnostics.Count != 0)
            {
                return;
            }
            var locales = files.Select(file => file.Locale!).Distinct().OrderBy(locale => locale, StringComparer.Ordinal).ToList();
            var hintName = target.Namespace is null ? target.Name : $"{target.Namespace}.{target.Name}";
            context.AddSource(
                $"{hintName.Replace("@", string.Empty)}.Localizer.g.cs",
                SourceText.From(LocalizerEmitter.Emit(target, root, locales), System.Text.Encoding.UTF8));
        }
    }
}
